from produire import produire,paras,steps,table
from medicaments import ibuprofene
parts=[
('Le {syndrome de la dent couronnée} est une inflammation cervicale haute associée à des dépôts cristallins péri-odontoïdiens. Il peut provoquer douleur intense, raideur et fièvre. Des calcifications seules ne suffisent pas au diagnostic.',paras('La dent est le processus odontoïde de la deuxième vertèbre cervicale. Des dépôts, souvent de pyrophosphate de calcium, peuvent entourer cette région et donner un aspect en couronne au scanner.', 'Le syndrome exige une concordance entre clinique inflammatoire, biologie et imagerie. Une calcification découverte fortuitement ne prouve pas la cause d’une douleur ou d’une fièvre.')),
('Le {terrain est souvent celui d’une personne âgée}. Une arthropathie microcristalline connue ou une poussée périphérique peut orienter. Le diagnostic peut toutefois être inaugural.',paras('Le cas pédagogique HUG associe cervicalgie aiguë, fièvre, limitation importante et épanchement du genou contenant des cristaux. Cet exemple aide au raisonnement sans fournir une fréquence suisse.', 'Une présentation précoce ou récidivante peut justifier une recherche de facteurs associés avec le rhumatologue. Ne pas déduire une maladie métabolique précise du seul aspect radiologique.')),
('Le {mécanisme est inflammatoire}. Les dépôts péri-odontoïdiens peuvent déclencher une réaction aiguë. La proximité de l’articulation haute explique la limitation marquée de rotation.',paras('Les dépôts peuvent exister sans symptômes et deviennent parfois inflammatoires. Les calcifications ne sont pas une prolifération tumorale ni, à elles seules, une infection.', 'Un syndrome inflammatoire biologique ne permet pas de distinguer immédiatement cette cause d’une méningite ou d’une infection rachidienne. Le contexte et les examens dirigés restent essentiels.')),
('Le {tri exclut d’abord les urgences concurrentes}. Raideur fébrile, altération générale ou signes neurologiques demandent une évaluation rapide. Ne pas conclure à une crise bénigne devant une simple calcification.',paras('Choc, confusion, purpura, déficit ou céphalée en coup de tonnerre imposent une filière urgente. L’hypothèse microcristalline ne doit pas retarder les soins d’une méningite ou d’une infection rachidienne.', 'Un déficit moteur, une marche anormale ou un trouble sphinctérien sort du tableau inflammatoire simple : rechercher compression ou autre complication, avec imagerie appropriée.')),
('L’{anamnèse caractérise une poussée cervicale haute}. Préciser début aigu ou subaigu, douleur occipitale et limitation de rotation. Rechercher fièvre, épisodes antérieurs et douleurs articulaires périphériques.',paras('Interroger sur arthropathie microcristalline connue, genou ou poignet gonflé, infection récente et immunosuppression. Demander traitements déjà pris et leur effet.', 'La réponse aux anti-inflammatoires peut soutenir une évolution favorable mais ne constitue pas une preuve exclusive. Une infection peut aussi paraître temporairement moins douloureuse sous ce traitement.')),
('L’{examen ne force pas la rotation}. Évaluer constantes, raideur et examen neurologique. Chercher une articulation périphérique inflammatoire et les signes d’un autre diagnostic.',paras('La limitation importante de rotation est évocatrice mais non spécifique. Rechercher atteinte méningée ou médullaire, porte d’entrée infectieuse et état général.', 'Une articulation chaude gonflée peut nécessiter une ponction pour cristaux et microbiologie. La présence de cristaux dans un prélèvement n’exclut pas à elle seule une infection associée.')),
('L’{approche syndromique compare inflammation et infection}. Le syndrome peut imiter méningite, spondylodiscite ou maladie inflammatoire systémique. La concordance du bilan permet de retenir la cause.',table(['Hypothèse','Éléments à rechercher'],[['Dent couronnée.','Douleur cervicale haute, rotation limitée, inflammation et dépôts péri-odontoïdiens concordants.'],['Méningite.','Céphalée, contexte infectieux, altération de conscience ; parcours urgent si suspectée.'],['Spondylodiscite.','Terrain infectieux, douleur persistante, lésions discovertébrales ou collection.'],['Autre inflammation.','Pseudopolyarthrite ou artérite à cellules géantes selon symptômes ; ne pas attribuer une menace visuelle à la nuque.']])) ,
('Le {diagnostic utilise le scanner cervical ciblé}. Le scanner montre bien les dépôts autour de l’odontoïde. La lecture doit être reliée au syndrome clinique.',paras('EULAR recommande le scanner lorsque l’atteinte microcristalline axiale est suspectée. Pour la dent couronnée, cette place repose sur la combinaison clinique, biologique et radiologique ; ne pas inventer une performance universelle.', 'La radiographie peut manquer les dépôts. L’IRM est utile si l’on recherche plutôt infection, compression ou autre atteinte des tissus mous ; les examens répondent à des questions différentes.')),
('Les {examens complémentaires dépendent des diagnostics encore possibles}. Les marqueurs inflammatoires évaluent le contexte. Cultures, ponction lombaire ou IRM ne sont réalisés que selon leurs indications propres.',paras('Ne pas imposer une ponction lombaire à tout scanner montrant des calcifications, mais ne pas l’écarter si une méningite reste plausible. La sécurité du geste et le délai thérapeutique relèvent alors du parcours infectieux.', 'En présence d’arthrite périphérique, l’analyse du liquide peut documenter les cristaux et rechercher une infection. Les critères de classification de maladie microcristalline destinés à la recherche ne remplacent pas ce jugement clinique.')),
('L’{algorithme établit la concordance avant traitement}. Les signes de gravité orientent d’abord vers l’urgence. La réponse ultérieure doit rester cohérente avec le diagnostic.',steps('Rechercher sepsis, signes méningés inquiétants, déficit et autres drapeaux rouges.', 'Évaluer syndrome inflammatoire et réaliser le scanner ciblé si l’hypothèse est pertinente.', 'Confronter dépôts, localisation douloureuse et examens ; exclure les diagnostics concurrents encore plausibles.', 'Choisir un traitement anti-inflammatoire adapté au terrain avec le clinicien.', 'Réévaluer rapidement si persistance, aggravation ou réponse inattendue.')),
('La {prise en charge suisse adapte le traitement au terrain}. Un anti-inflammatoire peut être discuté après exclusion des urgences. Insuffisance rénale, risques digestifs et cardiovasculaires sont particulièrement importants chez la personne âgée.',paras('La notice Brufen expose les doses des affections rhumatismales, mais ne nomme pas spécifiquement le syndrome de la dent couronnée. La fenêtre est un repère de spécialité et de sécurité ; elle ne démontre pas à elle seule une efficacité propre à ce syndrome.', '@@MEDICAMENTS@@', 'Les recommandations EULAR de traitement concernent la maladie à pyrophosphate de calcium en général, avec des preuves limitées et des extrapolations. Colchicine ou corticothérapie peuvent être envisagées par le spécialiste si les autres options sont inadaptées ; aucune dose non vérifiée n’est fournie ici. Ne pas commencer un corticoïde en éludant une infection encore plausible. Adapter le choix aux comédications et à la fonction rénale.', 'Éviter manipulation forcée et immobilisation prolongée systématique. La mobilisation reprend progressivement quand la douleur et les causes dangereuses le permettent.')),
('Le {suivi vérifie la résolution et les récidives}. Une amélioration attendue doit s’accompagner d’une évolution clinique cohérente. Des symptômes persistants imposent de reconsidérer le diagnostic.',paras('Donner une consigne de retour urgent devant fièvre croissante, altération de conscience ou signes neurologiques. Ne pas prolonger automatiquement un anti-inflammatoire sans contrôle de tolérance.', 'Discuter un bilan rhumatologique en cas de récidive ou d’autres articulations atteintes. Les dépôts peuvent persister à l’imagerie alors que la poussée a disparu ; leur disparition n’est pas un objectif obligatoire.')),
('Le {point clé} est la concordance clinique et radiologique. Le scanner est utile pour les dépôts péri-odontoïdiens. Une couronne calcifiée n’autorise pas à ignorer infection, saignement ou compression.',paras('Le diagnostic explique un syndrome inflammatoire précis, pas toute cervicalgie d’une personne âgée. La prudence thérapeutique dépend autant du terrain que de l’intensité douloureuse.'))]
quiz=[('Quelle structure est appelée dent ?','Le processus odontoïde de la deuxième vertèbre cervicale.'),('Les calcifications seules font-elles le diagnostic ?','Non.'),('Quel terrain est fréquent ?','La personne âgée avec ou sans arthropathie microcristalline connue.'),('La fièvre exclut-elle cette hypothèse ?','Non.'),('Un déficit neurologique fait-il partie d’une crise simple à banaliser ?','Non, rechercher une complication ou une autre cause.'),('Quel mouvement est souvent limité ?','La rotation cervicale.'),('Quel examen montre les dépôts ?','Le scanner cervical ciblé.'),('Une IRM a-t-elle exactement la même fonction ?','Non, elle aide notamment à rechercher infection ou compression.'),('Des cristaux excluent-ils une infection articulaire associée ?','Non.'),('Une ponction lombaire est-elle toujours nécessaire ?','Non, selon la suspicion de méningite et sa sécurité.'),('Peut-on ignorer une méningite devant des calcifications ?','Non.'),('Un corticoïde doit-il précéder l’exclusion d’une infection plausible ?','Non.'),('La réponse antalgique prouve-t-elle seule le diagnostic ?','Non.'),('Faut-il faire disparaître les dépôts pour conclure à une amélioration ?','Non, suivre surtout la clinique.')]
produire(9,parts,quiz,(1,12,23,25),ibuprofene)
